#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");size_t cycles=0;for(unsigned seed=0;seed<64;++seed){Graph g;g.header="<!-- dmx encoding binary 5 format sfm_session 20 -->\n";g.strings={"DmeTransform","test","orientation"};Element e{};e.type=0;e.name=1;e.id[0]=char(seed+1);Value v;v.wire.resize(16);e.attributes.push_back({2,13,{v}});g.elements.push_back(e);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(g,[](const std::string&,auto&){return 0xffffffffu;});std::array<float,4>next{float(seed+1),2,3,4};auto record=p.captureQuaternionUndo(0,"orientation",next);if(!p.setFloatComponents(0,"orientation",next,0))throw std::runtime_error("initial vector edit");auto equal=[&](const auto&value){return std::memcmp(p.graph.elements[0].attributes[0].values[0].wire.data(),value.data(),16)==0;};for(unsigned i=0;i<8;++i){if(!p.replayQuaternionUndo(record,true,0)||!equal(record.before)||!p.replayQuaternionUndo(record,false,0)||!equal(record.after))throw std::runtime_error("vector undo redo");++cycles;}p.typedAttributeFlags[0][0]|=0x20;if(p.replayQuaternionUndo(record,true,0)||!equal(record.after))throw std::runtime_error("protected replay");p.typedAttributeFlags[0][0]&=uint16_t(~0x20);if(!p.replayQuaternionUndo(record,true,3)||!equal(record.after))throw std::runtime_error("normal phase gate");auto missing=record;missing.name=0xffffffffu;if(p.replayQuaternionUndo(missing,true,0))throw std::runtime_error("missing name");if(p.scene.resolve(record.owner)->flags!=1||p.scene.queues.dirty.handles.size()!=1)throw std::runtime_error("vector dirty");p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.replayQuaternionUndo(record,true,0)||p.scene.size()||p.scene.attributes.size())throw std::runtime_error("stale undo");}std::cout<<"owned_quaternion_undo_redo_cycles="<<cycles<<" protection_phase_name_dirty_stale=passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
